var alpha = []string{"/", ":", "*", "a", "b", "c", "ab", "users", "1"}

func randWeird(r *rand.Rand) string {
	n := 1 + r.Intn(8)
	var sb strings.Builder
	for i := 0; i < n; i++ {
		sb.WriteString(alpha[r.Intn(len(alpha))])
	}
	s := sb.String()
	if r.Intn(3) == 0 {
		s = "/" + s
	}
	return s
}

func TestZZCharFuzz(t *testing.T) {
	r := rand.New(rand.NewSource(7))
	iters := 300000
	panics := 0
	hangs := 0
	for it := 0; it < iters && panics < 10 && hangs < 10; it++ {
		nRoutes := 1 + r.Intn(4)
		routes := []string{}
		for i := 0; i < nRoutes; i++ {
			routes = append(routes, randWeird(r))
		}
		e := New()
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					t.Errorf("ADD PANIC routes=%v: %v\n%s", routes, rec, debug.Stack())
					panics++
				}
			}()
			for _, rp := range routes {
				e.GET(rp, func(c Context) error { return nil })
			}
		}()
		if panics > 0 {
			continue
		}
		for k := 0; k < 3; k++ {
			p := randWeird(r)
			ctx := e.NewContext(nil, nil)
			done := make(chan struct{})
			var pan interface{}
			var stack []byte
			go func() {
				defer func() {
					if rec := recover(); rec != nil {
						pan = rec
						stack = debug.Stack()
					}
					close(done)
				}()
				e.router.Find(http.MethodGet, p, ctx)
			}()
			select {
			case <-done:
				if pan != nil {
					t.Errorf("FIND PANIC routes=%v path=%q: %v\n%s", routes, p, pan, stack)
					panics++
				}
			case <-time.After(3 * time.Second):
				t.Errorf("FIND HANG routes=%v path=%q", routes, p)
				hangs++
			}
		}
	}
	t.Logf("done iters=%d panics=%d hangs=%d", iters, panics, hangs)
	_ = fmt.Sprint
}
